#include "CurvatureBoundaryGraph.hpp"
#include <algorithm>
#include <cmath>
#include <functional>
#include <limits>
#include <map>
#include <numeric>
#include <queue>
#include <tuple>
#include <utility>

namespace Geometry::CurvatureSegmentation::BoundaryDetail
{
namespace
{
using Index = std::uint32_t;
using Labels = std::vector<Index>;
struct Link { Index To, EdgeId; };
using Adjacency = std::vector<std::vector<Link>>;
constexpr Index invalid = std::numeric_limits<Index>::max();

double Energy(std::span<const Edge> edges, const Labels& labels)
{
    double value = 0;
    for (const auto& e : edges) if (labels[e.A] != labels[e.B]) value += e.Cost;
    return value;
}

Index ConnectedLabels(const Adjacency& adjacency, Labels& labels)
{
    Labels compact(labels.size(), invalid), queue;
    Index count = 0;
    for (Index v = 0; v < labels.size(); ++v)
    {
        if (compact[v] != invalid) continue;
        queue.clear(); queue.push_back(v); compact[v] = count;
        for (std::size_t i = 0; i < queue.size(); ++i)
            for (auto link : adjacency[queue[i]])
                if (compact[link.To] == invalid && labels[link.To] == labels[v])
                { compact[link.To] = count; queue.push_back(link.To); }
        ++count;
    }
    labels.swap(compact);
    return count;
}

struct Aggregate { double Cost{}; bool Hard{}; };
struct Join
{
    double Gain; Index A, B;
    bool operator<(const Join& other) const
    {
        if (Gain != other.Gain) return Gain < other.Gain;
        return std::tie(A, B) > std::tie(other.A, other.B);
    }
};

bool Contract(std::span<const Edge> edges, Labels& labels, double tolerance,
              const Options& options, Result& result)
{
    const Index count = *std::max_element(labels.begin(), labels.end()) + 1;
    std::vector<std::map<Index, Aggregate>> graph(count);
    Labels parent(count); std::iota(parent.begin(), parent.end(), 0);
    for (auto e : edges)
    {
        Index a = labels[e.A], b = labels[e.B];
        if (a == b) continue;
        auto& x = graph[a][b]; x.Cost += e.Cost; x.Hard |= e.Hard;
        auto& y = graph[b][a]; y.Cost += e.Cost; y.Hard |= e.Hard;
    }
    std::priority_queue<Join> queue;
    const auto push = [&](Index a, Index b, const Aggregate& edge)
    {
        if (!edge.Hard && edge.Cost > tolerance)
            queue.push({edge.Cost, std::min(a,b), std::max(a,b)});
    };
    for (Index a = 0; a < count; ++a)
        for (const auto& [b, edge] : graph[a]) if (a < b) push(a,b,edge);
    while (!queue.empty())
    {
        auto candidate = queue.top(); queue.pop();
        Index a = candidate.A, b = candidate.B;
        if (parent[a] != a || parent[b] != b) continue;
        auto it = graph[a].find(b);
        if (it == graph[a].end() || it->second.Hard || it->second.Cost != candidate.Gain) continue;
        if (++result.AttemptedMoves > options.MaximumMoves) return false;
        // Merge the smaller sparse adjacency into the larger one.
        if (graph[a].size() < graph[b].size()) std::swap(a,b);
        graph[a].erase(b); graph[b].erase(a); parent[b] = a;
        for (const auto& [c, edge] : graph[b])
        {
            graph[c].erase(b);
            auto& target = graph[a][c];
            target.Cost += edge.Cost; target.Hard |= edge.Hard;
            graph[c][a] = target;
            push(a,c,target);
        }
        graph[b].clear();
        ++result.Contractions;
    }
    for (auto& label : labels)
    {
        Index root = label;
        while (parent[root] != root) root = parent[root];
        while (parent[label] != label) { Index next = parent[label]; parent[label] = root; label = next; }
        label = root;
    }
    return true;
}

struct Move
{
    double Gain; Index Vertex; std::uint64_t Version;
    bool operator<(const Move& other) const
    {
        if (Gain != other.Gain) return Gain < other.Gain;
        return Vertex > other.Vertex;
    }
};

// Temporary moves may disconnect a label. Connected components are relabeled
// after the pass, which changes no edge cut or objective value. Hard constraints
// hold even in temporary states; only the best improving prefix is committed.
bool RefinePair(Index a, Index b, const std::vector<Index>& vertices,
                const Adjacency& adjacency, std::span<const Edge> edges,
                Labels& labels, std::vector<std::uint64_t>& versions,
                std::vector<std::uint64_t>& locked, std::uint64_t stamp,
                double tolerance, const Options& options, Result& result,
                bool& improved)
{
    std::priority_queue<Move> queue;
    const auto push = [&](Index v)
    {
        if (locked[v] == stamp) return;
        const Index from = labels[v], to = from == a ? b : a;
        double gain = 0;
        bool valid = true;
        for (auto link : adjacency[v])
        {
            auto e = edges[link.EdgeId]; const Index other = labels[link.To];
            if (other == to) { gain += e.Cost; if (e.Hard) valid = false; }
            else if (other == from) gain -= e.Cost;
        }
        const auto version = ++versions[v];
        if (valid) queue.push({gain,v,version});
    };
    for (auto v : vertices) push(v);
    std::vector<std::pair<Index,Index>> history;
    history.reserve(vertices.size());
    double cumulative = 0, best = tolerance;
    std::size_t prefix = 0;
    while (!queue.empty())
    {
        const auto move = queue.top(); queue.pop();
        const Index v = move.Vertex;
        if (locked[v] == stamp || versions[v] != move.Version) continue;
        if (++result.AttemptedMoves > options.MaximumMoves)
        {
            for (auto it = history.rbegin(); it != history.rend(); ++it) labels[it->first] = it->second;
            return false;
        }
        locked[v] = stamp;
        history.emplace_back(v, labels[v]);
        labels[v] = labels[v] == a ? b : a;
        cumulative += move.Gain;
        if (cumulative > best) { best = cumulative; prefix = history.size(); }
        for (auto link : adjacency[v])
            if (labels[link.To] == a || labels[link.To] == b) push(link.To);
    }
    for (std::size_t i = history.size(); i > prefix; --i)
        labels[history[i-1].first] = history[i-1].second;
    if (prefix) { result.AcceptedMoves += prefix; improved = true; }
    return true;
}
}

Result Solve(Index nodes, std::span<const Edge> input, const Options& options)
{
    Result result;
    if (!nodes || !options.MaximumSweeps || !options.MaximumMoves || options.ExactNodeLimit > 8 ||
        !std::isfinite(options.RelativeTolerance) || options.RelativeTolerance < 0 || options.RelativeTolerance > 1e-6)
        return result;
    std::vector<Edge> edges(input.begin(),input.end());
    for (auto& e : edges)
    {
        if (e.A >= nodes || e.B >= nodes || e.A == e.B || !std::isfinite(e.Cost)) return result;
        if (e.B < e.A) std::swap(e.A,e.B);
    }
    std::sort(edges.begin(),edges.end(),[](auto a, auto b)
    { return std::tie(a.A,a.B,a.Cost,a.Hard) < std::tie(b.A,b.B,b.Cost,b.Hard); });
    Adjacency adjacency(nodes);
    double scale = 0;
    for (Index i = 0; i < edges.size(); ++i)
    {
        auto e = edges[i];
        adjacency[e.A].push_back({e.B,i}); adjacency[e.B].push_back({e.A,i});
        scale += std::abs(e.Cost);
        result.LowerBound += e.Hard ? e.Cost : std::min(0.0,e.Cost);
    }
    if (!std::isfinite(scale) || !std::isfinite(result.LowerBound)) return result;
    const double tolerance = scale * options.RelativeTolerance;
    Labels labels(nodes); std::iota(labels.begin(),labels.end(),0);
    result.InitialEnergy = Energy(edges, labels);
    if (nodes <= options.ExactNodeLimit)
    {
        Labels candidate(nodes,0), bestLabels = labels;
        double best = result.InitialEnergy;
        const auto enumerate = [&](auto&& self, Index v, Index maximum) -> bool
        {
            if (v == nodes)
            {
                if (++result.AttemptedMoves > options.MaximumMoves) return false;
                const double value = Energy(edges,candidate);
                if (value < best || (value == best && candidate < bestLabels)) { best=value; bestLabels=candidate; }
                return true;
            }
            for (Index label=0; label<=maximum+1; ++label)
            {
                bool feasible = true;
                for (auto link : adjacency[v])
                    if (link.To < v && edges[link.EdgeId].Hard && candidate[link.To] == label)
                    { feasible=false; break; }
                if (!feasible) continue;
                candidate[v]=label;
                if (!self(self,v+1,std::max(maximum,label))) return false;
            }
            return true;
        };
        if (!enumerate(enumerate,1,0)) { result.State=Status::WorkLimit; return result; }
        labels=std::move(bestLabels); result.Exact=true;
    }
    else
    {
        if (!Contract(edges,labels,tolerance,options,result)) { result.State=Status::WorkLimit; return result; }
        ConnectedLabels(adjacency,labels);
        std::vector<std::uint64_t> versions(nodes), locked(nodes);
        std::uint64_t stamp=0;
        bool converged=false;
        for (Index sweep=0; sweep<options.MaximumSweeps; ++sweep)
        {
            ++result.Sweeps;
            const double before=Energy(edges,labels);
            const Index count=*std::max_element(labels.begin(),labels.end())+1;
            // Pairs are reconstructed each sweep; graph storage is sparse.
            std::map<std::pair<Index,Index>,bool> pairs;
            for (auto e : edges)
                if (labels[e.A]!=labels[e.B]) pairs[{std::min(labels[e.A],labels[e.B]),std::max(labels[e.A],labels[e.B])}]=true;
            // Membership is updated after each accepted prefix, without whole-graph scans per pair.
            std::vector<std::vector<Index>> members(count*2);
            std::vector<Index> position(nodes);
            for (Index v=0; v<nodes; ++v) { position[v]=static_cast<Index>(members[labels[v]].size()); members[labels[v]].push_back(v); }
            bool improved=false;
            const auto refine = [&](Index a, Index b) -> bool
            {
                std::vector<Index> vertices=members[a];
                vertices.insert(vertices.end(),members[b].begin(),members[b].end());
                if (vertices.size()<2) return true;
                std::sort(vertices.begin(),vertices.end());
                std::vector<Index> prior; prior.reserve(vertices.size());
                for (auto v : vertices) prior.push_back(labels[v]);
                if (!RefinePair(a,b,vertices,adjacency,edges,labels,versions,locked,++stamp,tolerance,options,result,improved)) return false;
                for (std::size_t i=0;i<vertices.size();++i)
                {
                    const Index v=vertices[i], old=prior[i], now=labels[v];
                    if (old==now) continue;
                    auto& from=members[old]; const Index last=from.back();
                    from[position[v]]=last; position[last]=position[v]; from.pop_back();
                    position[v]=static_cast<Index>(members[now].size()); members[now].push_back(v);
                }
                return true;
            };
            for (const auto& [pair,unused] : pairs)
                if (!members[pair.first].empty() && !members[pair.second].empty() && !refine(pair.first,pair.second))
                { result.State=Status::WorkLimit; return result; }
            for (Index a=0; a<count; ++a)
                if (!refine(a,count+a)) { result.State=Status::WorkLimit; return result; }
            ConnectedLabels(adjacency,labels);
            const auto contractions=result.Contractions;
            if (!Contract(edges,labels,tolerance,options,result)) { result.State=Status::WorkLimit; return result; }
            ConnectedLabels(adjacency,labels);
            const double after=Energy(edges,labels);
            if (!std::isfinite(after) || after > before+tolerance)
            { result.State=Status::InvariantFailure; return result; }
            if (!improved && contractions==result.Contractions) { converged=true; break; }
        }
        if (!converged) { result.State=Status::WorkLimit; return result; }
    }
    ConnectedLabels(adjacency,labels);
    for (auto e : edges) if (e.Hard && labels[e.A]==labels[e.B])
    { result.State=Status::InvariantFailure; return result; }
    result.Energy=Energy(edges,labels);
    if (!std::isfinite(result.Energy) || result.Energy>result.InitialEnergy+tolerance || result.Energy<result.LowerBound-tolerance)
    { result.State=Status::InvariantFailure; return result; }
    result.Labels=std::move(labels); result.State=Status::Success;
    return result;
}
}

