// Private graph seam for the curvature-boundary CPU solver and its exact-oracle tests.
#pragma once
#include <cstdint>
#include <span>
#include <vector>
namespace Geometry::CurvatureSegmentation::BoundaryDetail
{
struct Edge { std::uint32_t A{}, B{}; double Cost{}; bool Hard{}; };
struct Options
{
    std::uint32_t MaximumSweeps{8};
    std::uint64_t MaximumMoves{2000000};
    double RelativeTolerance{1e-12};
    // Zero forces the heuristic in oracle-comparison tests.
    std::uint32_t ExactNodeLimit{8};
};
enum class Status { Success, InvalidInput, WorkLimit, InvariantFailure };
struct Result
{
    Status State{Status::InvalidInput};
    std::vector<std::uint32_t> Labels;
    double InitialEnergy{}, Energy{}, LowerBound{};
    std::uint64_t AttemptedMoves{}, AcceptedMoves{}, Contractions{};
    std::uint32_t Sweeps{};
    bool Exact{};
};
Result Solve(std::uint32_t nodes, std::span<const Edge> edges, const Options& options = {});
}

