module;
#include "CurvatureBoundaryGraph.hpp"
#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <limits>
#include <glm/glm.hpp>
module Geometry.HalfedgeMesh.CurvatureSegmentation.Multicut;
import Geometry.HalfedgeMesh;

namespace Geometry::CurvatureSegmentation
{
const char* ToString(BoundaryPartitionStatus s) noexcept
{
    switch(s)
    {
    case BoundaryPartitionStatus::Success: return "success";
    case BoundaryPartitionStatus::EmptyMesh: return "empty_mesh";
    case BoundaryPartitionStatus::UnsupportedSubmeshView: return "unsupported_submesh_view";
    case BoundaryPartitionStatus::InvalidParameters: return "invalid_parameters";
    case BoundaryPartitionStatus::InvalidEvidence: return "invalid_evidence";
    case BoundaryPartitionStatus::NonFinitePosition: return "non_finite_position";
    case BoundaryPartitionStatus::NonTriangleFace: return "non_triangle_face";
    case BoundaryPartitionStatus::DegenerateFace: return "degenerate_face";
    case BoundaryPartitionStatus::InvalidTopology: return "invalid_topology";
    case BoundaryPartitionStatus::WorkLimit: return "work_limit";
    case BoundaryPartitionStatus::InvariantFailure: return "invariant_failure";
    }
    return "unknown";
}

BoundaryPartitionResult PartitionFeatureBoundaries(
    const HalfedgeMesh::Mesh& mesh, const FeatureEvidenceView evidence,
    const BoundaryPartitionParams& params)
{
    using Clock=std::chrono::steady_clock;
    const auto started=Clock::now();
    const auto elapsed=[](auto start) { return std::chrono::duration<double,std::milli>(Clock::now()-start).count(); };
    BoundaryPartitionResult result;
    auto& d=result.Diagnostics;
    const auto finish=[&](BoundaryPartitionStatus s)
    {
        d.Status=s; d.TotalMilliseconds=elapsed(started);
        if(s!=BoundaryPartitionStatus::Success)
        { result.FaceRegions.clear(); result.EdgeBoundaries.clear(); result.RegionAreas.clear(); }
        return std::move(result);
    };
    constexpr auto invalid=std::numeric_limits<std::uint32_t>::max();
    if(mesh.FaceCount()==0) return finish(BoundaryPartitionStatus::EmptyMesh);
    if(mesh.IsSubmeshView()) return finish(BoundaryPartitionStatus::UnsupportedSubmeshView);
    if(!std::isfinite(params.FeatureWeight) || params.FeatureWeight<0 ||
       !params.MaximumMoves || !params.MaximumSweeps ||
       !std::isfinite(params.RelativeEnergyTolerance) || params.RelativeEnergyTolerance<0 ||
       params.RelativeEnergyTolerance>1e-6 || mesh.FaceCount()>=invalid/2 || mesh.EdgeCount()>=invalid)
        return finish(BoundaryPartitionStatus::InvalidParameters);
    if(evidence.HardEdgeMask.size()!=mesh.EdgesSize() || evidence.SoftEdgeConfidence.size()!=mesh.EdgesSize())
        return finish(BoundaryPartitionStatus::InvalidEvidence);
    for(std::size_t e=0;e<mesh.EdgesSize();++e)
        if(evidence.HardEdgeMask[e]>1 || !std::isfinite(evidence.SoftEdgeConfidence[e]) ||
           evidence.SoftEdgeConfidence[e]<0 || evidence.SoftEdgeConfidence[e]>1)
            return finish(BoundaryPartitionStatus::InvalidEvidence);
    glm::dvec3 lower{std::numeric_limits<double>::infinity()}, upper{-std::numeric_limits<double>::infinity()};
    for(auto v:mesh.LiveVertices())
    {
        const glm::dvec3 p{mesh.Position(v)};
        if(!std::isfinite(p.x)||!std::isfinite(p.y)||!std::isfinite(p.z))
            return finish(BoundaryPartitionStatus::NonFinitePosition);
        if(mesh.IsIsolated(v)||!mesh.IsManifold(v)) return finish(BoundaryPartitionStatus::InvalidTopology);
        lower=glm::min(lower,p); upper=glm::max(upper,p);
    }
    const double diagonal=glm::length(upper-lower);
    if(!std::isfinite(diagonal)||!(diagonal>0)) return finish(BoundaryPartitionStatus::DegenerateFace);
    d.BoundingBoxDiagonal=diagonal; d.FaceCount=mesh.FaceCount();
    std::vector<std::uint32_t> faceToNode(mesh.FacesSize(),invalid), nodeToFace;
    std::vector<double> areas;
    for(auto f:mesh.LiveFaces())
    {
        if(mesh.Valence(f)!=3) return finish(BoundaryPartitionStatus::NonTriangleFace);
        std::array<glm::dvec3,3> p; std::size_t i=0;
        for(auto v:mesh.VerticesAroundFace(f))
        {
            if(i==3||!v.IsValid()||!mesh.IsValid(v)||mesh.IsDeleted(v)) return finish(BoundaryPartitionStatus::InvalidTopology);
            p[i++]=glm::dvec3(mesh.Position(v));
        }
        if(i!=3) return finish(BoundaryPartitionStatus::NonTriangleFace);
        // Normalize before multiplying to keep area conditioning scale invariant.
        const double area=0.5*glm::length(glm::cross((p[1]-p[0])/diagonal,(p[2]-p[0])/diagonal));
        if(!std::isfinite(area)||!(area>0)) return finish(BoundaryPartitionStatus::DegenerateFace);
        faceToNode[f.Index]=static_cast<std::uint32_t>(nodeToFace.size());
        nodeToFace.push_back(f.Index); areas.push_back(area);
    }
    std::vector<BoundaryDetail::Edge> edges;
    std::vector<std::uint32_t> edgeSlots;
    std::vector<double> lengths;
    edges.reserve(mesh.EdgeCount()); edgeSlots.reserve(mesh.EdgeCount()); lengths.reserve(mesh.EdgeCount());
    for(auto e:mesh.LiveEdges())
    {
        auto h0=mesh.Halfedge(e,0), h1=mesh.Halfedge(e,1);
        if(!h0.IsValid()||!h1.IsValid()||!mesh.IsValid(h0)||!mesh.IsValid(h1)||mesh.Edge(h0)!=e||mesh.Edge(h1)!=e)
            return finish(BoundaryPartitionStatus::InvalidTopology);
        auto from=mesh.FromVertex(h0), to=mesh.ToVertex(h0);
        if(!from.IsValid()||!to.IsValid()||!mesh.IsValid(from)||!mesh.IsValid(to)||
           mesh.IsDeleted(from)||mesh.IsDeleted(to)||from==to)
            return finish(BoundaryPartitionStatus::InvalidTopology);
        const double length=glm::length(glm::dvec3(mesh.Position(from))-glm::dvec3(mesh.Position(to)))/diagonal;
        if(!std::isfinite(length)||!(length>0)) return finish(BoundaryPartitionStatus::DegenerateFace);
        auto f0=mesh.Face(h0), f1=mesh.Face(h1);
        for(auto f:{f0,f1})
            if(f.IsValid()&&(!mesh.IsValid(f)||mesh.IsDeleted(f))) return finish(BoundaryPartitionStatus::InvalidTopology);
        if(!f0.IsValid()&&!f1.IsValid()) return finish(BoundaryPartitionStatus::InvalidTopology);
        if(!f0.IsValid()||!f1.IsValid()) continue;
        if(f0==f1) return finish(BoundaryPartitionStatus::InvalidTopology);
        const double cost=length*(1-params.FeatureWeight*evidence.SoftEdgeConfidence[e.Index]);
        if(!std::isfinite(cost)) return finish(BoundaryPartitionStatus::InvalidParameters);
        edges.push_back({faceToNode[f0.Index],faceToNode[f1.Index],cost,evidence.HardEdgeMask[e.Index]!=0});
        edgeSlots.push_back(e.Index); lengths.push_back(length);
    }
    d.TransitionCount=edges.size(); d.AssemblyMilliseconds=elapsed(started);
    const auto solveStart=Clock::now();
    auto solved=BoundaryDetail::Solve(static_cast<std::uint32_t>(nodeToFace.size()),edges,
        {.MaximumSweeps=params.MaximumSweeps,.MaximumMoves=params.MaximumMoves,.RelativeTolerance=params.RelativeEnergyTolerance});
    d.SolveMilliseconds=elapsed(solveStart); d.AttemptedMoves=solved.AttemptedMoves;
    d.AcceptedMoves=solved.AcceptedMoves; d.Contractions=solved.Contractions; d.Sweeps=solved.Sweeps;
    d.Exact=solved.Exact; d.InitialEnergy=solved.InitialEnergy; d.FinalEnergy=solved.Energy; d.LowerBound=solved.LowerBound;
    if(solved.State!=BoundaryDetail::Status::Success)
        return finish(solved.State==BoundaryDetail::Status::WorkLimit?BoundaryPartitionStatus::WorkLimit:BoundaryPartitionStatus::InvariantFailure);
    d.RegionCount=*std::max_element(solved.Labels.begin(),solved.Labels.end())+1;
    result.FaceRegions.assign(mesh.FacesSize(),invalid); result.EdgeBoundaries.assign(mesh.EdgesSize(),0);
    result.RegionAreas.assign(d.RegionCount,0);
    for(std::size_t v=0;v<nodeToFace.size();++v)
    { result.FaceRegions[nodeToFace[v]]=solved.Labels[v]; result.RegionAreas[solved.Labels[v]]+=areas[v]; }
    for(std::size_t i=0;i<edges.size();++i)
    {
        const auto e=edges[i];
        if(solved.Labels[e.A]==solved.Labels[e.B]) continue;
        result.EdgeBoundaries[edgeSlots[i]]=1; ++d.BoundaryCount; d.BoundaryLength+=lengths[i];
        if(e.Hard) ++d.HardBoundaryCount;
        else if(evidence.SoftEdgeConfidence[edgeSlots[i]]>0) ++d.SoftBoundaryCount;
        else ++d.ClosureBoundaryCount;
        if(e.Hard||evidence.SoftEdgeConfidence[edgeSlots[i]]>0) d.SupportedLength+=lengths[i];
        else d.ClosureLength+=lengths[i];
    }
    return finish(BoundaryPartitionStatus::Success);
}
}

// Partitions an embedded triangle surface using signed feature-boundary costs;
// exposes a CPU diagnostic candidate without changing geometry or production defaults.
module;
#include <cstddef>
#include <cstdint>
#include <vector>
export module Geometry.HalfedgeMesh.CurvatureSegmentation.Multicut;
export import Geometry.HalfedgeMesh.CurvatureSegmentation.Features;
import Geometry.HalfedgeMesh;
export namespace Geometry::CurvatureSegmentation
{
enum class BoundaryPartitionStatus : std::uint8_t
{
    Success, EmptyMesh, UnsupportedSubmeshView, InvalidParameters, InvalidEvidence,
    NonFinitePosition, NonTriangleFace, DegenerateFace, InvalidTopology,
    WorkLimit, InvariantFailure
};
struct BoundaryPartitionParams
{
    double FeatureWeight{4.0};
    std::uint32_t MaximumSweeps{8};
    std::uint64_t MaximumMoves{2000000};
    double RelativeEnergyTolerance{1e-12};
};
struct BoundaryPartitionDiagnostics
{
    BoundaryPartitionStatus Status{BoundaryPartitionStatus::EmptyMesh};
    std::size_t FaceCount{}, TransitionCount{}, RegionCount{}, BoundaryCount{};
    std::size_t HardBoundaryCount{}, SoftBoundaryCount{}, ClosureBoundaryCount{};
    std::uint64_t AttemptedMoves{}, AcceptedMoves{}, Contractions{};
    std::uint32_t Sweeps{};
    bool Exact{};
    double BoundingBoxDiagonal{}, InitialEnergy{}, FinalEnergy{}, LowerBound{};
    double BoundaryLength{}, SupportedLength{}, ClosureLength{};
    double AssemblyMilliseconds{}, SolveMilliseconds{}, TotalMilliseconds{};
};
struct BoundaryPartitionResult
{
    // Successful arrays use source slots; deleted face slots are UINT32_MAX.
    // Failed results expose diagnostics only, never a partial partition.
    std::vector<std::uint32_t> FaceRegions;
    std::vector<std::uint8_t> EdgeBoundaries;
    std::vector<double> RegionAreas;
    BoundaryPartitionDiagnostics Diagnostics;
    [[nodiscard]] bool Succeeded() const noexcept
    { return Diagnostics.Status == BoundaryPartitionStatus::Success; }
};
[[nodiscard]] const char* ToString(BoundaryPartitionStatus status) noexcept;
// H/F are borrowed, slot-aligned evidence. Hard constraints apply to interior
// edges; source boundary edges do not separate two surface faces.
[[nodiscard]] BoundaryPartitionResult PartitionFeatureBoundaries(
    const HalfedgeMesh::Mesh& mesh, FeatureEvidenceView evidence,
    const BoundaryPartitionParams& params = {});
}

