#include <algorithm>
#include <cmath>
#include <limits>
#include <numeric>
#include <random>
#include <vector>
#include <gtest/gtest.h>
#include <glm/glm.hpp>
#include "CurvatureBoundaryGraph.hpp"
import Geometry.HalfedgeMesh;
import Geometry.Properties;
import Geometry.HalfedgeMesh.CurvatureSegmentation.Multicut;

namespace
{
namespace B=Geometry::CurvatureSegmentation::BoundaryDetail;
namespace C=Geometry::CurvatureSegmentation;
using Labels=std::vector<std::uint32_t>;
double Cost(const std::vector<B::Edge>& edges,const Labels& labels)
{
    double value=0;
    for(auto e:edges)
    {
        if(e.Hard&&labels[e.A]==labels[e.B]) return std::numeric_limits<double>::infinity();
        if(labels[e.A]!=labels[e.B]) value+=e.Cost;
    }
    return value;
}
// Independent exhaustive assignments, including redundant label permutations.
double BruteCost(std::uint32_t n,const std::vector<B::Edge>& edges)
{
    Labels labels(n); double best=std::numeric_limits<double>::infinity();
    std::uint64_t combinations=1; for(std::uint32_t i=0;i<n;++i) combinations*=n;
    for(std::uint64_t code=0;code<combinations;++code)
    {
        auto remaining=code;
        for(auto& label:labels) { label=remaining%n; remaining/=n; }
        best=std::min(best,Cost(edges,labels));
    }
    return best;
}
struct Grid
{
    Geometry::HalfedgeMesh::Mesh Mesh;
    std::vector<std::uint8_t> Hard;
    std::vector<double> Soft;
};
Grid MakeGrid(bool alternate=false,bool gap=false)
{
    Grid g; std::vector<Geometry::VertexHandle> vertices;
    for(int y=0;y<=8;++y) for(int x=0;x<=8;++x) vertices.push_back(g.Mesh.AddVertex({float(x),float(y),0}));
    for(int y=0;y<8;++y) for(int x=0;x<8;++x)
    {
        auto a=vertices[y*9+x],b=vertices[y*9+x+1],c=vertices[(y+1)*9+x+1],d=vertices[(y+1)*9+x];
        if(alternate) { EXPECT_TRUE(g.Mesh.AddTriangle(a,b,d)); EXPECT_TRUE(g.Mesh.AddTriangle(b,c,d)); }
        else { EXPECT_TRUE(g.Mesh.AddTriangle(a,b,c)); EXPECT_TRUE(g.Mesh.AddTriangle(a,c,d)); }
    }
    g.Hard.resize(g.Mesh.EdgesSize()); g.Soft.resize(g.Mesh.EdgesSize());
    for(auto e:g.Mesh.LiveEdges())
    {
        auto h=g.Mesh.Halfedge(e,0);
        auto a=g.Mesh.Position(g.Mesh.FromVertex(h)),b=g.Mesh.Position(g.Mesh.ToVertex(h));
        if(a.x==4&&b.x==4&&(!gap||std::min(a.y,b.y)!=4)) g.Soft[e.Index]=1;
    }
    return g;
}
}

TEST(CurvatureBoundaryGraph, ExactOracleMatchesIndependentAssignments)
{
    std::mt19937 random(319);
    for(int sample=0;sample<40;++sample)
    {
        std::vector<B::Edge> edges;
        for(std::uint32_t a=0;a<5;++a) for(std::uint32_t b=a+1;b<5;++b)
            if(random()%3) edges.push_back({a,b,double(int(random()%11)-5),random()%11==0});
        auto r=B::Solve(5,edges);
        ASSERT_EQ(r.State,B::Status::Success); EXPECT_TRUE(r.Exact);
        EXPECT_DOUBLE_EQ(r.Energy,BruteCost(5,edges)); EXPECT_DOUBLE_EQ(r.Energy,Cost(edges,r.Labels));
        EXPECT_LE(r.LowerBound,r.Energy);
    }
}

TEST(CurvatureBoundaryGraph, HardCutCannotBeBypassedThroughPositivePath)
{
    std::vector<B::Edge> edges{{0,1,100,false},{1,2,100,false},{0,2,1,true}};
    for(auto exact:{0u,8u})
    {
        auto r=B::Solve(3,edges,{.ExactNodeLimit=exact});
        ASSERT_EQ(r.State,B::Status::Success); EXPECT_NE(r.Labels[0],r.Labels[2]);
        EXPECT_DOUBLE_EQ(r.Energy,101);
    }
}

TEST(CurvatureBoundaryGraph, WiderMovesRecoverAcrossPrematureContraction)
{
    std::vector<B::Edge> edges;
    for(std::uint32_t a=0;a<6;++a) for(std::uint32_t b=a+1;b<6;++b)
        edges.push_back({a,b,a/3==b/3?5.0:(a==2&&b==3?9.0:-2.0),false});
    auto r=B::Solve(6,edges,{.ExactNodeLimit=0});
    ASSERT_EQ(r.State,B::Status::Success);
    EXPECT_DOUBLE_EQ(r.Energy,BruteCost(6,edges));
}

TEST(CurvatureBoundaryGraph, HeuristicIsFeasibleDeterministicAndBoundedByOracle)
{
    std::mt19937 random(912);
    for(int sample=0;sample<80;++sample)
    {
        std::vector<B::Edge> edges;
        for(std::uint32_t a=0;a<7;++a) for(std::uint32_t b=a+1;b<7;++b)
            if(random()%2) edges.push_back({a,b,double(int(random()%15)-7),random()%13==0});
        auto exact=B::Solve(7,edges), r=B::Solve(7,edges,{.ExactNodeLimit=0});
        ASSERT_EQ(r.State,B::Status::Success)<<sample;
        EXPECT_FALSE(r.Exact); EXPECT_GE(r.Energy,exact.Energy);
        EXPECT_DOUBLE_EQ(r.Energy,Cost(edges,r.Labels)); EXPECT_LE(r.Energy,r.InitialEnergy);
        std::reverse(edges.begin(),edges.end());
        for(auto& e:edges) std::swap(e.A,e.B);
        auto repeated=B::Solve(7,edges,{.ExactNodeLimit=0});
        EXPECT_EQ(r.Labels,repeated.Labels); EXPECT_DOUBLE_EQ(r.Energy,repeated.Energy);
    }
}

TEST(CurvatureBoundaryGraph, InvalidAndLimitedInputsReturnNoPartition)
{
    for(auto edges:{std::vector<B::Edge>{{0,3,1,false}},std::vector<B::Edge>{{0,0,1,false}},
                    std::vector<B::Edge>{{0,1,std::numeric_limits<double>::infinity(),false}}})
