TEST(CurvatureBoundaryPartition, HomogeneousSurfaceStaysWholeAndPreservesTopology)
{
    auto g=MakeGrid(); std::fill(g.Soft.begin(),g.Soft.end(),0.0);
    auto vertices=g.Mesh.VertexCount(),faces=g.Mesh.FaceCount(),edges=g.Mesh.EdgeCount();
    auto r=C::PartitionFeatureBoundaries(g.Mesh,{g.Hard,g.Soft});
    ASSERT_TRUE(r.Succeeded()); EXPECT_EQ(r.Diagnostics.RegionCount,1); EXPECT_EQ(r.Diagnostics.BoundaryCount,0);
    EXPECT_EQ(g.Mesh.VertexCount(),vertices); EXPECT_EQ(g.Mesh.FaceCount(),faces); EXPECT_EQ(g.Mesh.EdgeCount(),edges);
}

TEST(CurvatureBoundaryPartition, UniformScalePreservesPartitionAndObjective)
{
    auto g=MakeGrid(false,true); auto r=C::PartitionFeatureBoundaries(g.Mesh,{g.Hard,g.Soft}); ASSERT_TRUE(r.Succeeded());
    for(auto v:g.Mesh.LiveVertices()) g.Mesh.Position(v)*=1000.0f;
    auto scaled=C::PartitionFeatureBoundaries(g.Mesh,{g.Hard,g.Soft}); ASSERT_TRUE(scaled.Succeeded());
    EXPECT_EQ(r.FaceRegions,scaled.FaceRegions); EXPECT_NEAR(r.Diagnostics.FinalEnergy,scaled.Diagnostics.FinalEnergy,1e-12);
}

TEST(CurvatureBoundaryPartition, InvalidEvidenceAndBudgetFailClosed)
{
    auto g=MakeGrid(); g.Soft[0]=std::numeric_limits<double>::quiet_NaN();
    auto r=C::PartitionFeatureBoundaries(g.Mesh,{g.Hard,g.Soft});
    EXPECT_EQ(r.Diagnostics.Status,C::BoundaryPartitionStatus::InvalidEvidence); EXPECT_TRUE(r.FaceRegions.empty());
    g.Soft[0]=0; C::BoundaryPartitionParams p; p.MaximumMoves=1;
    r=C::PartitionFeatureBoundaries(g.Mesh,{g.Hard,g.Soft},p);
    EXPECT_EQ(r.Diagnostics.Status,C::BoundaryPartitionStatus::WorkLimit); EXPECT_TRUE(r.FaceRegions.empty());
}

