            result.Diagnostics.HardFeatureEdgeCount,
            shared.FeatureEdgeCount);
        EXPECT_TRUE(std::ranges::all_of(
            result.EdgeRawConfidence,
            [](const double value) { return value == 0.0; }));
        EXPECT_TRUE(std::ranges::all_of(
            result.SoftEdgeConfidence,
            [](const double value) { return value == 0.0; }));
